{
  "title": "Ligar para marcar uma visita",
  "situation": "Você viu um anúncio de um apartamento na Pine Street. Ligue para a proprietária, Sarah, para perguntar o preço e marcar um horário para visitar o local.",
  "character": {
    "name": "Sarah",
    "role": "proprietária",
    "place": "Pine Street Apartments"
  },
  "characterBrief": "You are a friendly but busy landlord. Keep your speech simple for an A2 learner. The apartment is 1200 dollars a month, and the rent includes water and electricity. You are available this Wednesday at 4 PM or Thursday at 10 AM. When the student asks for a time, say that the first time they suggest is already booked and offer the other one. End the call by confirming the address.",
  "objectives": [
    {
      "label": "Ask about availability",
      "description": "Pergunte se o apartamento na Pine Street ainda está disponível."
    },
    {
      "label": "Ask about rent",
      "description": "Pergunte quanto custa o aluguel mensal."
    },
    {
      "label": "Book a viewing",
      "description": "Sugira um dia e um horário para visitar o apartamento."
    }
  ],
  "openingLine": "Hi, this is Sarah from Pine Street Apartments. How can I help you?",
  "hints": [
    "Is the apartment on Pine Street still available?",
    "How much is the monthly rent?",
    "Does the rent include water and electricity?",
    "Can I see the apartment this week?",
    "Is Thursday at 10 AM okay for a visit?"
  ]
}

{
  "title": "Llamar para rentar un departamento",
  "situation": "You saw an ad for an apartment in Condesa, Mexico City. Call the landlord, Diego, to ask about the rent and book a time to see the place.",
  "character": {
    "name": "Diego",
    "role": "propietario",
    "place": "Condesa"
  },
  "characterBrief": "Diego is friendly, polite, and speaks clearly at an A2 level. He is renting an apartment in Condesa for $12,000 MXN per month, which includes water and gas but not electricity. He is available to show the place on Tuesday at 4:00 p.m. or Thursday at 10:00 a.m. When the learner asks for an appointment, he should first say Tuesday at 4:00 p.m. is already taken and suggest Thursday instead. He needs to end the call by saying goodbye and looking forward to the meeting.",
  "objectives": [
    {
      "label": "Preguntar el precio",
      "description": "Ask how much the rent for the apartment costs."
    },
    {
      "label": "Preguntar qué incluye",
      "description": "Ask if water and gas are included in the price."
    },
    {
      "label": "Programar una visita",
      "description": "Ask to see the apartment and agree on a day and time."
    }
  ],
  "openingLine": "Hola, hablas con Diego. ¿En qué te puedo ayudar sobre el departamento en la Condesa?",
  "hints": [
    "¿Cuánto cuesta la renta al mes?",
    "¿La renta incluye el agua y el gas?",
    "¿Puedo visitar el departamento el jueves a las diez de la mañana?",
    "Muchas gracias, nos vemos el jueves."
  ]
}
